/* \u4EE5\u4E0B\u4E24\u6BB5\u8986\u76D6\u5BBF\u4E3B SegmentedTabs \u7684\u80F6\u56CA\u5916\u89C2\u3002\u9009\u62E9\u5668\u4F9D\u8D56\u539F\u8BED\u6E32\u67D3\u51FA\u7684\u7ED3\u6784\uFF1A
   \u5BB9\u5668 [role=tablist] \u7684\u9996\u4E2A\u5B50\u5143\u7D20\u662F aria-hidden \u7684\u6ED1\u52A8\u6307\u793A\u5668\uFF0C\u5176\u540E\u624D\u662F\u5404 [role=tab]\u3002
   \u5347\u7EA7 @deepseek-ai/dsh-client-ui-primitives \u65F6\u5FC5\u987B\u590D\u6838\u8BE5\u7ED3\u6784\uFF0C\u5426\u5219\u8FD9\u4E9B\u89C4\u5219\u4F1A\u9759\u9ED8\u5931\u6548\u3002 */
